import { CHAIN_V1_FIXTURE } from './chain-v1-fixture.js'

/**
 * The chain fixture in the BSV stack's cross-language conformance vector format
 * (`conformance/VECTOR-FORMAT.md` in bsv-blockchain/ts-stack), as a pure mapping
 * from the bespoke object. `fixtures/vectors/dpp/chain/v1.json` is this
 * function's output, verbatim, and `fixture-json.test.ts` holds the two
 * identical, so the chain is the first fixture whose two forms are both
 * generated by tests (`fixtures/README.md`, "Two forms, one set of bytes").
 *
 * The vectors publish the test private keys so a writer in any language
 * reproduces the pinned bytes rather than only checking them. Vector identifiers
 * are permanent once published and the file is append-only: a corrected
 * expectation is a new vector, never an edit, and a vector whose rule the
 * standard cuts stays in the file, skipped, with its reason.
 */
const PRIVATE_KEYS: Record<string, string> = {
  maker: '11'.repeat(32),
  server: '22'.repeat(32),
  owner1: '33'.repeat(32),
  owner2: '44'.repeat(32),
  owner3: '55'.repeat(32),
}

const STATE_DESCRIPTIONS = [
  'Genesis: ACTIVATE by the maker, locked to the maker. Sign the twelve data fields as actor and as service, then build the fourteen-field script and the one-output transaction (spec record-model.md sections 2, 5 and 6).',
  'SOLD by the maker, spending the genesis output. The DPP output sits at index 1 behind an OP_RETURN, so a reader tracks the outpoint rather than assuming index 0. Ownership does not move on SOLD.',
  'TRANSFER to the second owner, signed by the first owner, whose identity key is the previous field 6.',
  'REPAIRED by the second owner: event_data carries the operation metadata, payload and owner unchanged.',
  "TRANSFER by the second owner to the third owner's per-passport owner key, derived from the third owner's root under [1, 'dpp owner v1'] with the passport identifier as key identifier and counterparty self (spec record-model.md section 3). The output is locked to that same key: the possession convention (spec custody.md section 3).",
  "TRANSFER by the third owner, acting under their root, to the first owner's per-passport owner key, again locked to it. event_data carries the third owner's BRC-69 linkage scalar under owner_linkage, a property no reader interprets (spec record-model.md section 3, field 9). The input is spent by the third owner's wallet through the PushDrop unlock under the owner protocol, one derivation and no key export; RFC 6979 nonces make the unlocking script reproducible.",
]

/**
 * The seven refusals of the owner-signed transfer (`owner-consent@1`), as
 * published until it was removed on 12 November 2026. The bespoke fixture no
 * longer carries them; their vectors keep their identifiers, bytes and
 * expectations, skipped, and `chain-fixture.test.ts` holds each to be a valid
 * chain under the record model alone, which is what the skip reason says.
 */
export const SUPERSEDED_OWNER_CONSENT_REFUSALS: Array<{ name: string; description: string; appendAfter: number; rawTx: string; error: string; acceptedUnder?: { authorities: string[] } }> = [
  {
    name: "transferByStranger",
    description:
      "A TRANSFER spending state 5 (owner: owner 3's derived key) made by owner 2, who no longer owns it, with empty event_data. Under the owner-signed transfer neither equality nor linkage holds; without the option the state is a valid TRANSFER, which is the whole reason the option exists.",
    appendAfter: 4,
    rawTx:
      "",
    error: "TRANSFER actor is not the previous owner and event_data carries no owner_linkage",
  },
  {
    name: "transferByFormerOwner",
    description:
      "A TRANSFER spending state 4 (owner: owner 2's identity key) made by owner 1, the previous owner, with no linkage. The equality form compares against the previous state's owner, never an earlier one.",
    appendAfter: 3,
    rawTx:
      "",
    error: "TRANSFER actor is not the previous owner and event_data carries no owner_linkage",
  },
  {
    name: "wrongOwnerLinkage",
    description:
      "Owner 3 acting under the right root, but event_data carries owner 2's scalar for this passport: well-formed, and reaching a different key. Refused at the point addition.",
    appendAfter: 4,
    rawTx:
      "",
    error: "owner_linkage does not link actor_identity_key to the previous owner_identity_key",
  },
  {
    name: "ownerLinkageUpperCase",
    description:
      "The correct scalar spelled in upper-case hex. One value has one spelling; refused before any arithmetic.",
    appendAfter: 4,
    rawTx:
      "",
    error: "owner_linkage must be 64 lower-case hex characters",
  },
  {
    name: "ownerLinkageShort",
    description:
      "The correct scalar missing its last character: 63 hex characters. Refused as malformed, not tried as a number.",
    appendAfter: 4,
    rawTx:
      "",
    error: "owner_linkage must be 64 lower-case hex characters",
  },
  {
    name: "ownerLinkageNotObject",
    description:
      "event_data is a JSON array holding the correct scalar. Valid JSON, not an object, so there is no owner_linkage property to read.",
    appendAfter: 4,
    rawTx:
      "",
    error: "TRANSFER actor is not the previous owner and event_data carries no owner_linkage",
  },
  {
    name: "recoveryWithoutAuthority",
    description:
      "A TRANSFER spending state 6 made by the maker, with a stated reason and no proof of consent. Refused under the option alone; accepted when the maker is a configured transfer authority (acceptedUnder), which is what a recovery looks like.",
    appendAfter: 5,
    rawTx:
      "",
    error: "TRANSFER actor is not the previous owner and event_data carries no owner_linkage",
    acceptedUnder: { authorities: ["034f355bdcb7cc0af728ef3cceb9615d90684bb5b2ca5f859ab0f0b704075871aa"] },
  },
]

const OWNER_CONSENT_SKIP_REASON =
  'Superseded: the owner-signed transfer (owner-consent@1) was removed on 12 November 2026, so no reader selects it; under the record model alone these bytes are a valid chain.'

const kebab = (name: string): string => name.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase())

export function chainV1Vectors(F: typeof CHAIN_V1_FIXTURE = CHAIN_V1_FIXTURE) {
  const stateVectors = F.states.map((s, i) => {
    const prev = i === 0 ? undefined : F.states[i - 1]
    return {
      id: `state-${i + 1}-${s.data.op.toLowerCase()}${s.unlock === 'owner' ? '-linked' : ''}`,
      description: STATE_DESCRIPTIONS[i],
      input: {
        data: s.data,
        actor_private_key_hex: PRIVATE_KEYS[s.actor],
        server_private_key_hex: PRIVATE_KEYS.server,
        locking_key_hex: s.lockingKey,
        ...(prev == null
          ? {}
          : { previous_raw_tx_hex: prev.rawTx, previous_output_index: prev.outputIndex }),
        op_return_first: s.outputIndex === 1,
        unlock: s.unlock,
        ...(s.unlock === 'owner'
          ? { unlock_protocol: F.ownerProtocol, unlock_key_id: s.data.passportId, unlock_counterparty: 'self' }
          : {}),
        signature_nonce: 'rfc6979',
      },
      expected: {
        user_signature_hex: s.userSignature,
        server_signature_hex: s.serverSignature,
        locking_script_hex: s.lockingScript,
        output_index: s.outputIndex,
        txid_hex: s.txid,
        raw_tx_hex: s.rawTx,
      },
      tags: ['happy-path', 'brc-42', 'brc-43', 'brc-48'],
    }
  })

  const ownerKeyVectors = [
    {
      id: 'owner-key-owner3',
      description:
        "The third owner's per-passport owner key and its linkage scalar (spec record-model.md section 3, spec custody.md section 2, spec record-model-v2.md section 6). The key is the root derived under the owner protocol with the passport identifier as key identifier and counterparty self; the scalar is the BRC-42 HMAC for that derivation, which only the root can compute, and owner_key = root_public_key + linkage times G, which anyone can check.",
      input: {
        root_private_key_hex: PRIVATE_KEYS.owner3,
        passport_id: F.states[0].data.passportId,
        protocol: F.ownerProtocol,
        counterparty: 'self',
      },
      expected: {
        root_public_key_hex: F.owner3Key,
        owner_key_hex: F.owner3OwnerKey,
        linkage_hex: F.owner3OwnerLinkage,
        linkage_verifies: true,
      },
      tags: ['happy-path', 'brc-42', 'brc-43'],
    },
    {
      id: 'owner-key-owner1',
      description: "The first owner's per-passport owner key, the field 6 the sixth state transfers to, from the same derivation.",
      input: {
        root_private_key_hex: PRIVATE_KEYS.owner1,
        passport_id: F.states[0].data.passportId,
        protocol: F.ownerProtocol,
        counterparty: 'self',
      },
      expected: {
        root_public_key_hex: F.owner1Key,
        owner_key_hex: F.owner1OwnerKey,
      },
      tags: ['happy-path', 'brc-42', 'brc-43'],
    },
  ]

  // The published verify vector selected the owner-signed transfer and
  // expected its verdict per state; it stays, skipped, and the chain is pinned
  // again without the option under a new identifier.
  const supersededVerifyVector = {
    id: 'verify-chain',
    description:
      'Verify the six raw transactions as a chain, genesis to tip, with the owner-signed transfer selected and no header source: every user signature verifies, every link holds, every server signature verifies under the service key, inclusion is pending, and the owner-signed transfer holds on the three TRANSFER states and is not applicable elsewhere (null). Scripts are not run by the verifier; the network ran them.',
    input: {
      raw_tx_hex: F.states.map((s) => s.rawTx),
      server_identity_key_hex: F.serverKey,
      owner_consent: true,
    },
    expected: {
      valid: true,
      spv: 'pending',
      states: F.states.map((s) => ({
        op: s.data.op,
        user_signature_valid: true,
        server_signature_valid: true,
        linkage_valid: true,
        owner_consent_valid: s.data.op === 'TRANSFER' ? true : null,
      })),
    },
    tags: ['happy-path', 'brc-42', 'brc-43'],
    skip: true,
    skip_reason: 'Superseded: the owner-signed transfer was removed on 12 November 2026, so the owner_consent input and the owner_consent_valid expectations name nothing; see verify-chain-record-model.',
  }

  const verifyVector = {
    id: 'verify-chain-record-model',
    description:
      'Verify the six raw transactions as a chain, genesis to tip, under the record model alone with no header source: every user signature verifies, every link holds, every server signature verifies under the service key, and inclusion is pending. Scripts are not run by the verifier; the network ran them.',
    input: {
      raw_tx_hex: F.states.map((s) => s.rawTx),
      server_identity_key_hex: F.serverKey,
    },
    expected: {
      valid: true,
      spv: 'pending',
      states: F.states.map((s) => ({
        op: s.data.op,
        user_signature_valid: true,
        server_signature_valid: true,
        linkage_valid: true,
      })),
    },
    tags: ['happy-path', 'brc-42', 'brc-43'],
  }

  const refusalVectors = F.refusals.map((r) => ({
    id: `refuse-${kebab(r.name)}`,
    description: r.description,
    input: {
      raw_tx_hex: [...F.states.slice(0, r.appendAfter + 1).map((s) => s.rawTx), r.rawTx],
    },
    expected: {
      accepted: false,
      stage: 'chain',
      reason: r.error,
    },
    tags: ['error-case'],
  }))

  const supersededRefusalVectors = SUPERSEDED_OWNER_CONSENT_REFUSALS.map((r) => ({
    id: `refuse-${kebab(r.name)}`,
    description: r.description,
    input: {
      raw_tx_hex: [...F.states.slice(0, r.appendAfter + 1).map((s) => s.rawTx), r.rawTx],
      owner_consent: true,
    },
    expected: {
      accepted: false,
      stage: 'chain',
      reason: r.error,
      accepted_without_owner_consent: true,
      ...(r.acceptedUnder == null ? {} : { accepted_with_authorities: r.acceptedUnder.authorities }),
    },
    tags: ['error-case', 'brc-42'],
    skip: true,
    skip_reason: OWNER_CONSENT_SKIP_REASON,
  }))

  return {
    $schema:
      'https://raw.githubusercontent.com/bsv-blockchain/ts-stack/main/conformance/schema/vector.schema.json',
    id: 'dpp.chain.v1',
    name: 'DPP record model v1: a passport chain, its links, and the possession convention',
    brc: ['BRC-42', 'BRC-43', 'BRC-48'],
    version: '1.0.0',
    reference_impl: 'dpp-core@0.1.0',
    parity_class: 'required',
    vectors: [...stateVectors, ...ownerKeyVectors, supersededVerifyVector, ...refusalVectors, ...supersededRefusalVectors, verifyVector],
  }
}
